// SECURITY.md keeps model text out of commit messages. The one trailer added
// here is not model text: it is the gate-validated requester login, so G0's
// independent-approval check on main can see who asked for the fix and
// require an approval from someone else.
const REQUESTER_LOGIN = /^[A-Za-z0-9-]{1,39}$/;

function requestedBy(requester: string): string {
  if (!REQUESTER_LOGIN.test(requester)) {
    throw new Error("fix requester is not a GitHub login");
  }
  return `Requested-by: ${requester}`;
}

export function renderFixCommitMessage(input: { selection: FixSelection; plan: FixValidatedPlan; requester: string }): string {
  return [
    ...todaysCommitLines(input), // unchanged: finding ids and plain-path locations, closing keywords defused
    "",
    requestedBy(input.requester),
  ].join("\n");
}

// renderFixPrBody keeps its prose ("requested by @...") and adds the machine
// line G0's check reads in PR bodies:
//   `Requested-by: @${input.requester}`

// Sketch from G2-05's steps: G0-09's check also reads the trailers of Byte's fix commits on a main PR.
const TRAILER = /^Requested-by:\s*@?([A-Za-z0-9-]{1,39})\s*$/m;

export interface Commit { author: string; message: string; committedAt: string }
export class MissingRequester extends Error {}

export function fixRequesters(commits: Commit[], fixIdentity: string): { people: Set<string>; lastFixAt: string | null } {
  const fixes = commits.filter((c) => c.author.toLowerCase() === fixIdentity.toLowerCase());
  const people = new Set<string>();
  for (const fix of fixes) {
    const login = TRAILER.exec(fix.message)?.[1];
    if (!login) throw new MissingRequester("A Byte fix commit without a Requested-by trailer; failing closed.");
    people.add(login.toLowerCase());
  }
  const lastFixAt = fixes.map((c) => c.committedAt).sort().at(-1) ?? null; // ISO times sort as text
  return { people, lastFixAt };
}

// An approval counts only if it came after the last fix commit and from outside the set.
export const approvalCounts = (login: string, submittedAt: string, fix: ReturnType<typeof fixRequesters>): boolean =>
  !fix.people.has(login.toLowerCase()) && (fix.lastFixAt === null || submittedAt > fix.lastFixAt);

// Wilson score upper bound: the highest true rate the data still allows, at 95% confidence (z = 1.96).
export const wilsonUpper = (bad: number, n: number, z = 1.96): number => {
  if (n === 0) return 1; // no data: any rate is possible, so the bar fails closed
  const p = bad / n;
  const z2 = z * z;
  const centre = p + z2 / (2 * n);
  const spread = z * Math.sqrt((p * (1 - p)) / n + z2 / (4 * n * n));
  return (centre + spread) / (1 + z2 / n);
};

