import test from "node:test";
import assert from "node:assert/strict";
import { approvalCounts, fixRequesters, MissingRequester } from "../src/fix-requesters.js";

const FIX = "byte-fix"; // the lab's name for Byte's fix identity
const commits = [
  { author: "dana", message: "Add the export button", committedAt: "2026-11-02T09:00:00Z" },
  { author: FIX, message: "Fix 2 Byte findings\n\nRequested-by: omer", committedAt: "2026-11-02T10:00:00Z" },
];

test("the person who asked for the fix cannot approve it", () => {
  assert.equal(approvalCounts("omer", "2026-11-02T11:00:00Z", fixRequesters(commits, FIX)), false);
});
test("a teammate's approval after the fix counts", () => {
  assert.equal(approvalCounts("lior", "2026-11-02T11:00:00Z", fixRequesters(commits, FIX)), true);
});
test("an approval from before the fix does not count", () => {
  assert.equal(approvalCounts("lior", "2026-11-02T09:30:00Z", fixRequesters(commits, FIX)), false);
});
test("a fix commit without the trailer fails closed", () => {
  assert.throws(() => fixRequesters([{ author: FIX, message: "Fix", committedAt: "2026-11-02T10:00:00Z" }], FIX), MissingRequester);
});

