import { wilsonUpper } from "./wilson.js";

// One row per fcp push in observe mode: the sniff's verdict and what the paired full review found (lab shape).
export interface SniffPair { allFixed: boolean; verdict: "fulfilled" | "unfulfilled"; sure: boolean; reflagged: boolean }

export function goLive(pairs: SniffPair[]) {
  const skips = pairs.filter((p) => p.verdict === "fulfilled" && p.sure); // live mode would skip these reviews
  const falseFulfilled = skips.filter((p) => p.reflagged).length; // ...but the full review flagged it again
  const allFixed = pairs.filter((p) => p.allFixed);
  const skipped = allFixed.filter((p) => p.verdict === "fulfilled" && p.sure).length;
  const upper = wilsonUpper(falseFulfilled, skips.length);
  const skipRate = allFixed.length === 0 ? 0 : skipped / allFixed.length;
  return { sure: skips.length, upper, skipRate, live: upper <= 0.02 && skipRate >= 0.4 };
}

