import test from "node:test";
import assert from "node:assert/strict";
import { goLive, type SniffPair } from "../src/go-live.js";

const rows = (n: number, row: SniffPair): SniffPair[] => Array.from({ length: n }, () => row);
const skip: SniffPair = { allFixed: true, verdict: "fulfilled", sure: true, reflagged: false };
const review: SniffPair = { allFixed: true, verdict: "unfulfilled", sure: false, reflagged: false };
const wrong: SniffPair = { allFixed: false, verdict: "fulfilled", sure: true, reflagged: true };

test("60 clean skips are not enough evidence yet", () => {
  const result = goLive([...rows(60, skip), ...rows(40, review)]);
  assert.equal(result.live, false);
  assert.equal(result.upper.toFixed(3), "0.060");
});
test("299 clean skips and one wrong one pass both bars", () => {
  const result = goLive([...rows(299, skip), wrong, ...rows(200, review)]);
  assert.equal(result.live, true);
});
